existing = set()
for f in glob.glob("data/*.json"):
    if f.endswith(("directory_more.json", "howto_earn.json")): continue
    for u in re.findall(r'https?://[^"\s]+', open(f).read()): existing.add(u.rstrip("/").lower().replace("://www.", "://"))
key = lambda u: u.rstrip("/").lower().replace("://www.", "://")
def check(e):
    if e[3].startswith("#"): return e, "live", 200, "", ""
    r = subprocess.run(["curl", "-sSL", "-m", "20", "-A", "Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/124", "-o", "/tmp/dm_body", "-w", "%{http_code} %{url_effective}", e[3]] if False else
        ["bash", "-c", 'curl -skL --retry 1 -m 35 -A "Mozilla/5.0 Chrome/124" -w "\\n__CODE__%{http_code}" "$0" | tail -c 400000', e[3]], capture_output=True, text=True, errors="ignore")
    body, _, code = r.stdout.rpartition("__CODE__"); code = int(code or 0)
    title = (re.search(r"<title[^>]*>(.*?)</title>", body, re.S | re.I) or [None, ""])[1].strip()[:80]
    parked = len(body) < 15000 and re.search(r"domain (is )?for sale|this domain is parked|buy this domain|hugedomains\.com|sedoparking\.com", body, re.I)
    status = "live" if 200 <= code < 400 and not parked else "bot-protected" if code in (401, 403, 429, 503) else "dead"
    ph = e[6] if e[6] and re.search(r"\b" + re.escape(e[6]) + r"\b", body) else ""
    return e, status, code, title, ph
LISTCATS = ("Must-have apps", "Earn:", "Events &", "Meetups", "Promos", "Embassies", "Free language", "Learning centers", "Learn farming", "Recycle")
items, skipped = [], []
seen = set()
with cf.ThreadPoolExecutor(6) as ex:
    for e, st, code, title, ph in ex.map(check, [e for e in E]):
        if (key(e[3]) in existing and not e[0].startswith(LISTCATS)) or (e[0], key(e[3])) in seen: skipped.append((e[1], "already in directory")); continue
        if st == "dead": skipped.append((e[1], f"dead/parked (HTTP {code})")); continue
        seen.add((e[0], key(e[3])))
        it = {"cat": e[0], "name": e[1], "abbr": e[2], "url": e[3], "label": e[4], "desc": f"{e[5]} {e[4]}.", "link": st, "checked": "2026-10-29", "_title": title}
        if ph: it["phone"] = ph
        elif e[6]: skipped.append((e[1] + " hotline " + e[6], "number not found on fetched page; phone omitted"))
        items.append(it)
order = [x[0] for x in E]; items.sort(key=lambda i: (order.index(i["cat"]), i["name"]))
titles = {i["name"]: i.pop("_title") for i in items}
json.dump({"as_of": "2026-10-29", "note": "Curated high-utility sites. Brand listings are informational, not endorsements. Hotlines shown only when found on the official page.", "items": items}, open("data/directory_more.json", "w"), ensure_ascii=False, indent=1)
json.dump({"skipped": skipped, "titles": titles}, open("/tmp/dm_report.json", "w"), ensure_ascii=False, indent=1)
import collections; print(len(items), collections.Counter(i["cat"] for i in items)); print(*skipped, sep="\n")
